import importlib.util, itertools, random

def load(path):
    spec = importlib.util.spec_from_file_location("m", path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m

orig = load("/tmp/renewal_orig.py")
new = load("/tmp/eval-work-gxf99I/renewal.py")

# exhaustive over a compact domain
ids = ["", "a", 5]
statuses = [None, 1, "active", "lapsed", "suspended", "banned", "other"]
tiers = [None, "basic", "gold", "platinum", 3]
amounts = [None, 0, -5, 39, 40, 41, 55, 90, 91, 120, 135, 140, 145, "50", 200.5]
methods = [None, "card", "transfer", "cash", 1]
expired = [None, -1, 0, 10, 29, 30, 31, 100, "5", 2.5]
strikes = [None, -1, 0, 1, 2, 3, 4, "1", 1.5]

def make(overrides):
    member = overrides.get("member", {})
    payment = overrides.get("payment", {})
    return ({"id":"u1","status":"active","tier":"basic", **member},
            {"amount":40,"method":"card", **payment})

# full combinatorial on key axis values
combos = []
for s in statuses:
    for t in tiers:
        for a in amounts:
            for meth in methods:
                combos.append((make({"member":{"status":s,"tier":t},"payment":{"amount":a,"method":meth}})))
# targeted exhaustive for status-specific fields
for s in ["lapsed","active","suspended"]:
    for t in tiers:
        for a in amounts:
            for meth in methods:
                for ed in expired:
                    combos.append((make({"member":{"status":s,"tier":t,"expired_days":ed,"strikes":2},"payment":{"amount":a,"method":meth}})))
                for st in strikes:
                    combos.append((make({"member":{"status":s,"tier":t,"strikes":st,"expired_days":5},"payment":{"amount":a,"method":meth}})))

# random fuzz
random.seed(42)
for _ in range(20000):
    s = random.choice(["active","lapsed","suspended","banned","other",1,None])
    t = random.choice(["basic","gold","platinum",3,None])
    a = random.choice(amounts)
    meth = random.choice(methods)
    ed = random.choice(expired)
    st = random.choice(strikes)
    member={"status":s,"tier":t,"expired_days":ed,"strikes":st} if isinstance(s,str) else {"status":s,"tier":t}
    if random.random()<0.1: member["id"]=""
    combos.append((member, {"amount":a,"method":meth}))

bad=0
for (member,payment) in combos:
    try: o=orig.process_renewal(member,payment)
    except Exception as e: o=("EXC",type(e).__name__)
    try: n=new.process_renewal(member,payment)
    except Exception as e: n=("EXC",type(e).__name__)
    if o!=n:
        bad+=1
        if bad<20:
            print("DIFF:",repr(member),repr(payment))
            print("  orig:",o)
            print("  new :",n)
print("total diffs:",bad,"of",len(combos))
